import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float, max, min, abs, length, fract, step, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry, RingGeometry, DirectionalLight,
  } = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, fallback) =>
    (items.find((i) => i.role === role) || {}).text ?? fallback;
  const headlineCopy = findText('headline', 'Your ledger is empty.');
  const bodyCopy = findText(
    'body',
    'Commissioned pieces and saved references will appear here once you begin.'
  );
  const ctaCopy = findText('cta-label', 'BROWSE THE COLLECTION');

  const group = new Group();
  const tweens = [];
  const disposables = [];

  // ---- mount fade uniform (multiplied into every node-material opacity) ----
  const fadeU = uniform(0);

  // ============================================================
  // BACKDROP STAGE — 7x6 plane at z=-2.5, spec gradient stops
  // ============================================================
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial();
  {
    const u = uv();
    backMat.colorNode = mix(color('#14141a'), color('#0b0b10'), u.y.oneMinus());
  }
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backGeo, backMat);

  // ============================================================
  // PANEL — 3.2 x 2.2, corner radius 0.06, radial gradient,
  // hairline grid @ 0.25 pitch, 0.006 hairline border #26262f
  // ============================================================
  const panelGeo = new PlaneGeometry(3.2, 2.2);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.transparent = true;
  panelMat.roughness = 0.55;
  panelMat.metalness = 0.35;
  {
    const u = uv();
    const p = u.sub(0.5).mul(vec2(3.2, 2.2)); // panel-space units

    // rounded-rect SDF
    const r = float(0.06);
    const q = abs(p).sub(vec2(1.6 - 0.06, 1.1 - 0.06));
    const outer = length(max(q, 0.0));
    const inner = min(max(q.x, q.y), 0.0);
    const d = outer.add(inner).sub(r);

    // radial engineered gradient center -> edges
    const rad = length(p.div(vec2(1.6, 1.1)));
    const base = mix(color('#14141a'), color('#0b0b10'), smoothstep(0.0, 1.0, rad));

    // hairline grid at 0.25-unit pitch, #e8ecf2 @ 6%
    const gp = p.div(0.25);
    const lx = abs(fract(gp.x).sub(0.5));
    const ly = abs(fract(gp.y).sub(0.5));
    const gridMask = max(step(0.488, lx), step(0.488, ly));
    const withGrid = mix(base, color('#e8ecf2'), gridMask.mul(0.06));

    // 0.006 hairline border #26262f just inside the edge
    const borderMask = smoothstep(-0.014, -0.006, d);
    panelMat.colorNode = mix(withGrid, color('#26262f'), borderMask);

    // rounded alpha edge
    const alpha = float(1).sub(smoothstep(-0.004, 0.004, d));
    panelMat.opacityNode = alpha.mul(fadeU);
  }
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  group.add(panel);
  disposables.push(panelGeo, panelMat);

  // ============================================================
  // GHOST PREVIEW — wireframe watch-card left of center
  // ============================================================
  const ghost = new Group();
  ghost.position.set(-0.9, 0.15, 0.02);
  panel.add(ghost);

  const ghostLineU = uniform(0.3); // strokes @ 30%
  const ghostBarU = uniform(0.22); // bars @ 22%

  const lineMat = new MeshBasicNodeMaterial();
  lineMat.transparent = true;
  lineMat.colorNode = color('#e8ecf2');
  lineMat.opacityNode = ghostLineU.mul(fadeU);

  const barMat = new MeshBasicNodeMaterial();
  barMat.transparent = true;
  barMat.colorNode = color('#e8ecf2');
  barMat.opacityNode = ghostBarU.mul(fadeU);

  disposables.push(lineMat, barMat);

  const stroke = 0.008;
  const cardW = 1.1;
  const cardH = 1.4;

  // card outline: 4 hairline strokes
  const hGeo = new PlaneGeometry(cardW, stroke);
  const vGeo = new PlaneGeometry(stroke, cardH);
  disposables.push(hGeo, vGeo);

  const topEdge = new Mesh(hGeo, lineMat);
  topEdge.position.set(0, cardH / 2, 0);
  const botEdge = new Mesh(hGeo, lineMat);
  botEdge.position.set(0, -cardH / 2, 0);
  const leftEdge = new Mesh(vGeo, lineMat);
  leftEdge.position.set(-cardW / 2, 0, 0);
  const rightEdge = new Mesh(vGeo, lineMat);
  rightEdge.position.set(cardW / 2, 0, 0);
  ghost.add(topEdge, botEdge, leftEdge, rightEdge);

  // ghost dial circle, 0.55 diameter
  const dialGeo = new RingGeometry(0.275 - stroke, 0.275, 48);
  disposables.push(dialGeo);
  const dial = new Mesh(dialGeo, lineMat);
  dial.position.set(0, 0.25, 0);
  ghost.add(dial);

  // two ghost text bars 0.7 x 0.06
  const barGeo = new PlaneGeometry(0.7, 0.06);
  disposables.push(barGeo);
  const bar1 = new Mesh(barGeo, barMat);
  bar1.position.set(0, -0.4, 0);
  const bar2 = new Mesh(barGeo, barMat);
  bar2.position.set(0, -0.56, 0);
  ghost.add(bar1, bar2);

  // ghost breathe: 0.24 -> 0.34 yoyo 2400ms
  const breathe = { t: 0 };
  tweens.push(
    gsap.to(breathe, {
      t: 1,
      duration: 2.4,
      ease: 'sine.inOut',
      repeat: -1,
      yoyo: true,
      onUpdate: () => {
        const line = 0.24 + 0.1 * breathe.t;
        ghostLineU.value = line;
        ghostBarU.value = line * (0.22 / 0.3);
      },
    })
  );

  // ============================================================
  // COPY COLUMN — right of ghost, 0.5-unit padding
  // ============================================================
  const colX = 0.15;

  const headline = ctx.fontAtlas.createText(headlineCopy, {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 320,
  });
  headline.position.set(colX, 0.62, 0.02);
  panel.add(headline);

  const body = ctx.fontAtlas.createText(bodyCopy, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 300,
  });
  body.position.set(colX, 0.18, 0.02);
  panel.add(body);

  // ============================================================
  // ACCENT CTA — 1.5 x 0.36 extruded slab, vertical gradient,
  // edge emissive #ff2a38 @ 1.5
  // ============================================================
  const cta = new Group();
  cta.position.set(0.82, -0.62, 0.05);
  panel.add(cta);

  const ctaGeo = new BoxGeometry(1.5, 0.36, 0.06);
  const ctaMat = new MeshStandardNodeMaterial();
  ctaMat.transparent = true;
  ctaMat.roughness = 0.5;
  ctaMat.metalness = 0.25;
  {
    const u = uv();
    ctaMat.colorNode = mix(color('#c1121f'), color('#ff4450'), u.y);
    const ex = abs(u.x.sub(0.5)).mul(2);
    const ey = abs(u.y.sub(0.5)).mul(2);
    const edgeMask = smoothstep(0.86, 0.97, max(ex, ey));
    ctaMat.emissiveNode = color('#ff2a38').mul(edgeMask).mul(1.5);
    ctaMat.opacityNode = fadeU;
  }
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  cta.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);

  const ctaLabel = ctx.fontAtlas.createText(ctaCopy, {
    fontSize: 13,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 1.04,
  });
  ctaLabel.position.set(0, 0, 0.045);
  cta.add(ctaLabel);

  // ============================================================
  // FOREGROUND ACCENT — small signal-red index tick (depth plane 3)
  // ============================================================
  const tickGeo = new PlaneGeometry(0.22, 0.016);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.transparent = true;
  tickMat.colorNode = color('#ff2a38');
  tickMat.opacityNode = fadeU.mul(0.9);
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(-1.38, -1.28, 0.4);
  group.add(tick);
  disposables.push(tickGeo, tickMat);

  // ============================================================
  // NODE-LOCAL RIM LIGHT — accent hue grazing the panel grid
  // ============================================================
  const rim = new DirectionalLight(0xff2a38, 0.7);
  rim.position.set(-3, 1.5, 2.5);
  group.add(rim);

  const graze = new DirectionalLight(0xe8ecf2, 0.5);
  graze.position.set(3.5, 3, 1.2);
  group.add(graze);

  // ============================================================
  // MOUNT — fade-up: opacity 0 -> 1, y +0.2 -> 0, 500ms
  // ============================================================
  group.position.y = 0.2;
  const mountTl = gsap.timeline();
  mountTl.to(group.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  mountTl.to(fadeU, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tweens.push(mountTl);

  // ============================================================
  // HANDLERS
  // ============================================================
  let pressTl = null;
  group.userData.handlers = {
    click: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(cta.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' });
      pressTl.to(cta.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(1.7)' });
      tweens.push(pressTl);
      ctx.emit('navigate', { to: 'hub-collection' });
    },
    hover: () => {
      const t = gsap.to(cta.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.3, ease: 'power2.out' });
      tweens.push(t);
    },
    hoverOut: () => {
      const t = gsap.to(cta.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power2.out' });
      tweens.push(t);
    },
  };

  // ============================================================
  // CLEANUP
  // ============================================================
  group.userData.cleanup = () => {
    for (const t of tweens) t.kill();
    if (pressTl) pressTl.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    for (const textObj of [headline, body, ctaLabel]) {
      textObj.traverse((child) => {
        if (child.geometry && child.geometry.dispose) child.geometry.dispose();
        if (child.material && child.material.dispose) child.material.dispose();
      });
    }
    rim.dispose();
    graze.dispose();
  };

  return group;
}
